  'caption:chat-type': { label: 'チャット入力', doc: '吹き出しの文字が話すタイミングで打たれる。' },
  'caption:lyric-fill': { label: '歌詞', doc: '柔らかく光るクラシックな明朝体の白文字。歌っている語は金色に、まだの語は薄い。' },
  'caption:lyric-blur': { label: '歌詞ぼかし', doc: '歌詞の行がぼかしで出入りする。' },
  'caption:dialog-type': { label: 'ゲームの会話枠', doc: '二重枠の紺のゲーム会話ボックス。話すタイミングで文字が打たれる。' },
  'caption:dialog-roll': { label: '会話枠ロールアップ', doc: 'ゲームの会話枠が転がり上がり、縮んで消える。' },
  'caption:comic-bounce': { label: 'コマ', doc: '太い黒枠と網点の白いコマが伸び縮みして入る。' },
